/// 屏幕墙服务状态。
class WallStatusDto {
  /// 是否运行。
  final bool running;

  /// 缩略编码器后端。
  final String backend;

  /// 采集后端（如 `dxgi-desktop-duplication`）。
  final String captureBackend;

  /// 实测帧率（1 秒窗口）。
  final double fps;

  /// 已编码帧数。
  final BigInt encodedFrames;

  /// 已解码帧数。
  final BigInt decodedFrames;

  /// 重组丢弃帧数。
  final BigInt droppedFrames;

  /// 预览宽。
  final int width;

  /// 预览高。
  final int height;

  /// 最近端到端延迟（微秒）。
  final BigInt latencyUs;

  /// 最近帧时间戳（微秒）。
  final BigInt latestPtsUs;

  /// 最近错误。
  final String? lastError;

  const WallStatusDto({
    required this.running,
    required this.backend,
    required this.captureBackend,
    required this.fps,
    required this.encodedFrames,
    required this.decodedFrames,
    required this.droppedFrames,
    required this.width,
    required this.height,
    required this.latencyUs,
    required this.latestPtsUs,
    this.lastError,
  });

  @override
  int get hashCode =>
      running.hashCode ^
      backend.hashCode ^
      captureBackend.hashCode ^
      fps.hashCode ^
      encodedFrames.hashCode ^
      decodedFrames.hashCode ^
      droppedFrames.hashCode ^
      width.hashCode ^
      height.hashCode ^
      latencyUs.hashCode ^
      latestPtsUs.hashCode ^
      lastError.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WallStatusDto &&
          runtimeType == other.runtimeType &&
          running == other.running &&
          backend == other.backend &&
          captureBackend == other.captureBackend &&
          fps == other.fps &&
          encodedFrames == other.encodedFrames &&
          decodedFrames == other.decodedFrames &&
          droppedFrames == other.droppedFrames &&
          width == other.width &&
          height == other.height &&
          latencyUs == other.latencyUs &&
          latestPtsUs == other.latestPtsUs &&
          lastError == other.lastError;
}
